const std = @import("std"); const ctxz = @import("ct-ctrl-ctxz.zig"); const jobs = @import("ru-jobs-main.zig");
pub const Row = struct { id: []const u8, title: []const u8, level: u8, jobs: []const []const u8 };
pub const ROWS = [_]Row{ .{ .id = "J01", .title = "read unread chats", .level = 1, .jobs = &.{"read"} }, .{ .id = "J02", .title = "send text once", .level = 1, .jobs = &.{"send"} }, .{ .id = "J03", .title = "reminders", .level = 1, .jobs = &.{"remind"} }, .{ .id = "J04", .title = "pin chat", .level = 1, .jobs = &.{"pin"} }, .{ .id = "J05", .title = "mute chat", .level = 1, .jobs = &.{"mute"} }, .{ .id = "J06", .title = "new group", .level = 1, .jobs = &.{"group"} }, .{ .id = "J07", .title = "forward", .level = 1, .jobs = &.{"forward"} }, .{ .id = "J08", .title = "plain-language recipes", .level = 1, .jobs = &.{ "say", "reply", "summ" } }, .{ .id = "J09", .title = "AI draft (optional)", .level = 1, .jobs = &.{"reply"} }, .{ .id = "J10", .title = "quote-reply and @mention", .level = 1, .jobs = &.{ "quote", "send" } }, .{ .id = "J11", .title = "send image, video, file", .level = 1, .jobs = &.{"file"} }, .{ .id = "J12", .title = "stickers", .level = 1, .jobs = &.{"sticker"} }, .{ .id = "J13", .title = "reactions", .level = 1, .jobs = &.{"react"} }, .{ .id = "J14", .title = "recall and delete", .level = 1, .jobs = &.{ "recall", "delete" } }, .{ .id = "J15", .title = "search and open by name or phone", .level = 1, .jobs = &.{ "send", "canary" } }, .{ .id = "J16", .title = "history scroll", .level = 1, .jobs = &.{"read"} }, .{ .id = "J17", .title = "archive, hide, unread, pin message", .level = 1, .jobs = &.{ "archive", "hide", "unread", "pinmsg" } }, .{ .id = "J18", .title = "friends", .level = 1, .jobs = &.{ "friend", "accept", "ignore", "alias", "block" } }, .{ .id = "J19", .title = "message requests", .level = 1, .jobs = &.{ "reqaccept", "reqignore" } }, .{ .id = "J20", .title = "group admin", .level = 1, .jobs = &.{ "rename", "addmember", "delmember", "deputy", "leave" } }, .{ .id = "J21", .title = "polls", .level = 1, .jobs = &.{"poll"} }, .{ .id = "J22", .title = "notes", .level = 1, .jobs = &.{"note"} }, .{ .id = "J23", .title = "conversation labels", .level = 1, .jobs = &.{"label"} }, .{ .id = "J24", .title = "quick messages", .level = 1, .jobs = &.{ "quick", "usequick" } }, .{ .id = "J25", .title = "download one file", .level = 1, .jobs = &.{"download"} }, .{ .id = "J26", .title = "profile read", .level = 1, .jobs = &.{"profile"} }, .{ .id = "J27", .title = "My Cloud", .level = 1, .jobs = &.{"cloud"} }, .{ .id = "J28", .title = "watch loop", .level = 1, .jobs = &.{} }, .{ .id = "J29", .title = "export, report, retry, undo, backup", .level = 1, .jobs = &.{} }, .{ .id = "J30", .title = "voice message (spike, not built)", .level = 0, .jobs = &.{} }, .{ .id = "J31", .title = "log out", .level = 1, .jobs = &.{"logout"} }, .{ .id = "J32", .title = "logged-in devices, remote logout", .level = 1, .jobs = &.{ "devices", "devout" } }, .{ .id = "J33", .title = "notification setting", .level = 1, .jobs = &.{"notify"} }, .{ .id = "J34", .title = "interface language", .level = 1, .jobs = &.{"lang"} }, .{ .id = "J35", .title = "storage view", .level = 1, .jobs = &.{"storage"} }, .{ .id = "J36", .title = "help page", .level = 1, .jobs = &.{"help"} }, .{ .id = "J37", .title = "send feedback", .level = 1, .jobs = &.{"feedback"} }, .{ .id = "J38", .title = "change password (hand-off)", .level = 1, .jobs = &.{"passwd"} }, .{ .id = "J39", .title = "unfriend", .level = 1, .jobs = &.{"unfriend"} } };
pub fn covered(job: []const u8) bool { for (ROWS) |row| { for (row.jobs) |nam| { if (std.mem.eql(u8, nam, job)) return true; } } return false; }
pub fn matxRun(ctx: *ctxz.Ctx) !u8 { if (ctx.args.json) { try ctxz.emit(ctx, try std.json.Stringify.valueAlloc(ctx.allo, ROWS, .{})); try ctxz.emit(ctx, "\n"); return 0; } for (ROWS) |row| { const flat = try std.mem.join(ctx.allo, " ", row.jobs); try ctxz.emitf(ctx, "{s}  L{d}  {s}  [{s}]\n", .{ row.id, row.level, row.title, flat }); } try ctxz.emit(ctx, "L1 = green on the simulator. L2-L5 need the live campaign (owner + test account).\n"); _ = jobs.SPECS; return 0; }
